def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = rng.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        v = rng.normal(size=dim)
        v = clip(v + x) - clip(2*v*x + v)
        v = clip(v / (1e-7 + np.linalg.norm(v)))

        f = func(clip(best_x + 0.5 * v))
        if f < best_f:
            best_f = f
            best_x = best_x + 0.5 * v

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    current = rng.uniform(lb, ub, size=dim)
    best = current.copy()
    sigma = 0.1
    temperature = 100

    for _ in range(budget):
        new_candidate = clip(current + rng.normal(0, sigma, size=dim))
        delta = func(new_candidate) - func(best)

        if delta < 0 or np.random.rand() < np.exp(-delta / temperature):
            current = new_candidate
            if delta < 0:
                best = current.copy()
        else:
            probability = np.exp(-(func(current) - func(best)) / temperature)
            if rng.uniform(0, 1) < probability:
                current = best.copy()

        sigma *= 0.99
        temperature *= 0.999

    return best
